Schueler a = new Schueler("Lena");
Schueler b = new Schueler("Jonas");
Schueler c = new Schueler("Ali");

Console.WriteLine($"Angelegte Schüler: {Schueler.Anzahl}");
Console.WriteLine($"{c.Name} hat die Nummer {c.Nummer}.");
// Ausgabe:
// Angelegte Schüler: 3
// Ali hat die Nummer 3.

class Schueler
{
    public static int Anzahl;      // einmal für alle

    public string Name;            // pro Objekt
    public int Nummer;             // pro Objekt

    public Schueler(string name)
    {
        Name = name;
        Anzahl++;
        Nummer = Anzahl;
    }
}

Console.WriteLine(Umrechner.KmhInMs(36));
Console.WriteLine(Umrechner.Note(87));
Console.WriteLine(Umrechner.MaxPunkte);
// Ausgabe:
// 10
// Gut
// 100

static class Umrechner
{
    public const int MaxPunkte = 100;

    public static int KmhInMs(int kmh)
    {
        return kmh * 1000 / 3600;
    }

    public static string Note(int punkte)
    {
        if (punkte >= 90) return "Sehr gut";
        if (punkte >= 80) return "Gut";
        if (punkte >= 50) return "Bestanden";
        return "Nicht bestanden";
    }
}

Zaehler z = new Zaehler();
z.Klick();
Zaehler.Gesamt();

class Zaehler
{
    public static int gesamtKlicks;
    public int klicks;

    public void Klick()
    {
        klicks++;          // OK: eigenes Feld
        gesamtKlicks++;    // OK: statisches Feld
    }

    public static void Gesamt()
    {
        Console.WriteLine(gesamtKlicks);   // OK
        // Console.WriteLine(klicks);      // Fehler! Welches Objekt?
    }
}

